rn c >= 'A' && c <= 'Z'\\n                || c >= 'a' && c <= 'z'\\n                || c >= '0' && c <= '9'\\n                || c == '.' || c == '_' || c == '-';\\n    }\\n\\n    private static char toHex(int value) {\\n        return \\\"0123456789ABCDEF\\\".charAt(value);\\n    }\\n}\\n\",\"known_bad_label\":\"Reuses the parsed field map across records, causing fields from earlier records to leak into later outputs.\"}]}"}}
