{"items":[{"id":"cap-v2-ordering_and_selection-java-generation-01","test_code":"import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        testOrderingAndBoundaries();
        testEmptyAndNonMutation();
        testStableIdenticalRecords();
        testMalformedInputs();
    }

    private static void testOrderingAndBoundaries() {
        String[] requests = {
            "zeta|9|2",
            "beta|9|1",
            "Alpha|9|1",
            "low|0|0",
            "max_seq|5|9223372036854775807",
            "first|5|0"
        };
        assertListEquals(
            Arrays.asList(
                "Alpha|9|1",
                "beta|9|1",
                "zeta|9|2",
                "first|5|0",
                "max_seq|5|9223372036854775807",
                "low|0|0"
            ),
            Solution.prioritize(requests)
        );
    }

    private static void testEmptyAndNonMutation() {
        String[] empty = new String[0];
        assertListEquals(Arrays.asList(), Solution.prioritize(empty));

        String[] requests = {"b|1|2", "a|9|3", "c|1|1"};
        String[] snapshot = requests.clone();
        Solution.prioritize(requests);
        if (!Arrays.equals(snapshot, requests)) {
            throw new AssertionError("input array was modified");
        }
    }

    private static void testStableIdenticalRecords() {
        String first = new String("same|4|7");
        String second = new String("same|4|7");
        String[] requests = {first, "top|9|0", second};
