{"items":[{"id":"cap-v2-parsing_and_encoding-java-generation-02","test_code":"import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        assertListEquals(Collections.emptyList(), Solution.decodeDocument(""), "empty document");

        assertListEquals(
                Arrays.asList("hello world", "", "hello world"),
                Solution.decodeDocument("DEF greeting=hello world\nDEF empty=\nGET greeting\nGET empty\nGET greeting"),
                "definitions and GET order");

        assertListEquals(
                Arrays.asList("a=b=c", "  padded text  "),
                Solution.decodeDocument("DEF A1_value=a=b=c\nDEF Spaced=  padded text  \nGET A1_value\nGET Spaced"),
                "text preserves equals signs and spaces");

        assertListEquals(
                Arrays.asList("first", "second"),
                Solution.decodeDocument("DEF x=first\nGET x\nDEF y=second\nGET y"),
                "GET may precede later unrelated definitions");

        expectIllegalArgument(() -> Solution.decodeDocument("GET missing"), "undefined name");
        expectIllegalArgument(() -> Solution.decodeDocument("DEF 1bad=value"), "name beginning with digit");
        expectIllegalArgument(() -> Solution.decodeDocument("DEF bad-name=value"), "invalid name character");
        expectIllegalArgument(() -> Solution.decodeDocument("DEF name"), "definition without equals");
        expectIllegalArgument(() -> Solution.decodeDocument("GET name extra"), "GET with extra text");
        expectIllegalArgument(() -> Solution.decodeDocument(" GET name"), "leading whitespace in command");
        expectIllegalArgument(() -> Solution.decodeDocument("DEF x=one\nDEF x=two"), "duplicate definition");
        expectIllegalArgument(() -> Solution.decodeDocument("DEF x=one\n"), "trailing empty line");
        expectIllegalArgument(() -> Solution.decodeDocument("\n"), "empty lines in nonempty document");

        assertListEquals(Arrays.asList("one"), Solution.decodeDocument("DEF x=one\nGET x"),
                "first independent invocation");
        expectIllegalArgument(() -> Solution.decodeDocument("GET x"),
                "definitions must not leak between invocations");
        assertListEquals(Arrays.asList("two"), Solution.decodeDocument("DEF x=two\nGET x"),
                "name can be reused in another invocation");
    }

    private static void assertListEquals(List<String> expected, List<String> actual, String message) {
        if (!expected.equals(actual)) {
            throw new AssertionError(message + ": expected " + expected + " but was " + actual);
        }
    }

    private static void expectIllegalArgument(Runnable action, String message) {
        try {
            action.run();
        } catch (IllegalArgumentException expected) {
            return;
        }
        throw new AssertionError(message + ": expected IllegalArgumentException");
    }
}
