    public static void main(String[] args) {
        assertEquals("alpha,beta,gamma", Solution.normalizeCodes("alpha,beta,gamma"), "ordinary codes");
        assertEquals("alpha,beta", Solution.normalizeCodes("  alpha  , hold: beta  "),
                "tokens and marker remainder are trimmed");
        assertEquals("x", Solution.normalizeCodes("hold:x,x, hold: x "),
                "duplicates are detected after marker removal");
        assertEquals("x,y", Solution.normalizeCodes("x,hold:y,hold:x,y"),
                "first canonical occurrence determines order");
        assertEquals("hold:z,z", Solution.normalizeCodes("hold:hold:z,hold:z"),
                "only one leading marker is removed");
        assertEquals("HOLD:x,Hold:x,x", Solution.normalizeCodes("HOLD:x,Hold:x,hold:x"),
                "marker is case-sensitive");
        assertEquals("a b,c:d", Solution.normalizeCodes(" a b , hold: c:d "),
                "canonical codes may contain spaces and colons");
        assertEquals("code", Solution.normalizeCodes("code, code ,hold:code"),
                "whitespace variants deduplicate canonically");

        expectIllegalArgument(() -> Solution.normalizeCodes(""), "empty input token");
        expectIllegalArgument(() -> Solution.normalizeCodes("   "), "whitespace-only token");
        expectIllegalArgument(() -> Solution.normalizeCodes("hold:"), "empty marked code");
        expectIllegalArgument(() -> Solution.normalizeCodes("hold:   "), "empty trimmed marked code");
        expectIllegalArgument(() -> Solution.normalizeCodes("a,,b"), "empty middle token");
        expectIllegalArgument(() -> Solution.normalizeCodes("a,"), "empty final token");
