"},{"id":"cap-v2-parsing_and_encoding-java-repair-02","test_code":"public class SolutionTest {
    public static void main(String[] args) {
        assertEquals("", Solution.normalizeProperties(""), "empty input");
        assertEquals("a=1;b=2", Solution.normalizeProperties("b=2;a=1"), "keys are sorted");
        assertEquals("name=second", Solution.normalizeProperties("Name=first;NAME=second"),
                "normalized duplicate key uses last value");
        assertEquals("a=three;z=last", Solution.normalizeProperties("z=last;A=one;a=two;A=three"),
                "last value wins without changing sorted serialization");
        assertEquals("key=", Solution.normalizeProperties("KEY="), "empty value is allowed");
        assertEquals("a-b9=value", Solution.normalizeProperties("A-B9=value"),
                "valid key characters are normalized to lowercase");
        assertEquals("abc=x", Solution.normalizeProperties("%41%42%43=x"),
                "escaped key letters are decoded and normalized");
        assertEquals("v=%25%3B%3D", Solution.normalizeProperties("v=%25%3B%3D"),
                "reserved value characters are decoded then canonically encoded");
        assertEquals("v=hello world!~", Solution.normalizeProperties("v=hello world!~"),
                "printable value characters remain literal");
        assertEquals("v=A", Solution.normalizeProperties("v=%41"),
                "unnecessary value escapes are canonicalized to literals");
        assertEquals("a=two", Solution.normalizeProperties("%41=one;a=two"),
                "duplicate detection happens after key decoding and case folding");

        expectIllegalArgument(() -> Solution.normalizeProperties("novalue"), "missing equals");
        expectIllegalArgument(() -> Solution.normalizeProperties("=value"), "empty key");
        expectIllegalArgument(() -> Solution.normalizeProperties("a=b=c"), "multiple literal equals");
        expectIllegalArgument(() -> Solution.normalizeProperties("a=1;"), "empty trailing field");
        expectIllegalArgument(() -> Solution.normalizeProperties("a=1;;b=2"), "empty middle field");
        expectIllegalArgument(() -> Solution.normalizeProperties("a=%"), "incomplete escape");
        expectIllegalArgument(() -> Solution.normalizeProperties("a=%2"), "short escape");
        expectIllegalArgument(() -> Solution.normalizeProperties("a=%GG"), "non-hexadecimal escape");
        expectIllegalArgument(() -> Solution.normalizeProperties("a=%0A"), "decoded non-printable value");
        expectIllegalArgument(() -> Solution.normalizeProperties("bad_key=x"), "invalid key character");
        expectIllegalArgument(() -> Solution.normalizeProperties("bad%20key=x"),
                "decoded space is invalid in key");
        expectIllegalArgument(() -> Solution.normalizeProperties("a\tb=x"),
                "unescaped non-printable character");
        expectIllegalArgument(() -> Solution.normalizeProperties("a=x\ny"),
                "non-printable value character");
    }

    private static void assertEquals(String expected, String actual, String message) {
        if (!expected.equals(actual)) {
            throw new AssertionError(message + ": expected <" + expected + "> but was <" + actual + ">");
        }
    }

    private static void expectIllegalArgument(Runnable action, String message) {
        try {
            action.run();
        } catch (IllegalArgumentException expected) {
            return;
        }
        throw new AssertionError(message + ": expected IllegalArgumentException");
    }
